hooks.command:
node -e "
const input = JSON.parse(require('fs').readFileSync('/dev/stdin','utf8'));
const file = input.tool_input?.file_path || '';
if (!file.endsWith('.dart') || file.endsWith('.g.dart') || file.endsWith('.freezed.dart')) process.exit(0);
let claudeMd = '';
if (file.includes('/home/')) claudeMd = 'lib/home/CLAUDE.md';
else if (file.includes('/features/pdf/')) claudeMd = 'lib/features/pdf/CLAUDE.md';
else if (file.includes('/core/')) claudeMd = 'lib/core/CLAUDE.md';
if (!claudeMd) process.exit(0);
process.stdout.write(JSON.stringify({\n  type: 'text',\n  text: '⚠️  CLAUDE.md reminder: You edited ' + file.split('/lib/')[1] + ' — if you changed a public interface, class name, or added a feature, update ' + claudeMd + ' before finishing.'\n}));
"
